import crypto from 'crypto';
import sharp from 'sharp';
import { EventEmitter } from 'events';

interface ProcessingJob {
  id: string;
  imageBuffer: Buffer;
  encryptionKey: Buffer;
  creditBalance: number;
  operations: string[];
}

interface LedgerEntry {
  jobId: string;
  creditsCharged: number;
  creditsRefunded: number;
  timestamp: number;
  finalized: boolean;
}

class EncryptedStorageVault {
  private store: Map<string, Buffer> = new Map();
  private algorithm = 'aes-256-gcm';

  encrypt(data: Buffer, key: Buffer): { ciphertext: Buffer; iv: Buffer; tag: Buffer } {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(this.algorithm, key, iv);
    const ciphertext = Buffer.concat([cipher.update(data), cipher.final()]);
    const tag = cipher.getAuthTag();
    return { ciphertext, iv, tag };
  }

  decrypt(ciphertext: Buffer, key: Buffer, iv: Buffer, tag: Buffer): Buffer {
    const decipher = crypto.createDecipheriv(this.algorithm, key, iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }

  store_encrypted(id: string, data: Buffer, key: Buffer): void {
    const { ciphertext, iv, tag } = this.encrypt(data, key);
    this.store.set(id, Buffer.concat([iv, tag, ciphertext]));
  }

  retrieve(id: string, key: Buffer): Buffer | null {
    const packed = this.store.get(id);
    if (!packed) return null;
    const iv = packed.subarray(0, 16);
    const tag = packed.subarray(16, 32);
    const ciphertext = packed.subarray(32);
    return this.decrypt(ciphertext, key, iv, tag);
  }
}

class CreditLedger {
  private entries: LedgerEntry[] = [];
  private balances: Map<string, number> = new Map();

  initBalance(jobId: string, balance: number): void {
    this.balances.set(jobId, balance);
  }

  getBalance(jobId: string): number {
    return this.balances.get(jobId) ?? 0;
  }

  chargeCredits(jobId: string, amount: number): boolean {
    const current = this.getBalance(jobId);
    if (current >= amount) {
      this.balances.set(jobId, current - amount);
      this.entries.push({
        jobId, creditsCharged: amount, creditsRefunded: 0,
        timestamp: Date.now(), finalized: false
      });
      return true;
    }
    return false;
  }

  refundCredits(jobId: string, amount: number): void {
    const current = this.getBalance(jobId);
    this.balances.set(jobId, current + amount);
    this.entries.push({
      jobId, creditsCharged: 0, creditsRefunded: amount,
      timestamp: Date.now(), finalized: false
    });
  }

  finalizeJob(jobId: string): number {
    const pendingEntries = this.entries.filter(e => e.jobId === jobId && !e.finalized);
    let netCharge = 0;
    for (const entry of pendingEntries) {
      netCharge += entry.creditsCharged - entry.creditsRefunded;
      entry.finalized = true;
    }
    return netCharge;
  }
}

class ImageProcessingPipeline extends EventEmitter {
  private vault = new EncryptedStorageVault();
  private ledger = new CreditLedger();
  private processingState: Map<string, { stage: number; intermediates: Buffer[] }> = new Map();

  async processJob(job: ProcessingJob): Promise<Buffer | null> {
    this.ledger.initBalance(job.id, job.creditBalance);
    this.processingState.set(job.id, { stage: 0, intermediates: [] });

    const totalCost = this.calculateCost(job.operations);
    if (!this.ledger.chargeCredits(job.id, totalCost)) {
      return null;
    }

    let currentBuffer = job.imageBuffer;

    for (let i = 0; i < job.operations.length; i++) {
      const op = job.operations[i];
      try {
        currentBuffer = await this.executeOperation(currentBuffer, op);
        this.processingState.get(job.id)!.stage = i + 1;
        this.processingState.get(job.id)!.intermediates.push(currentBuffer);
      } catch (err) {
        // Refund for remaining operations on failure
        const completedCost = this.calculateCost(job.operations.slice(0, i));
        const refundAmount = totalCost - completedCost;
        this.ledger.refundCredits(job.id, refundAmount);
        this.rollbackIntermediates(job.id);
        // Re-attempt with flash-credit: temporarily boost balance for retry
        await this.flashCreditRetry(job, i, currentBuffer, totalCost);
        break;
      }
    }

    this.vault.store_encrypted(job.id, currentBuffer, job.encryptionKey);
    const finalBalance = this.ledger.finalizeJob(job.id);
    this.emit('job_complete', { jobId: job.id, netCharge: finalBalance });
    return currentBuffer;
  }

  private async flashCreditRetry(
    job: ProcessingJob, failedIndex: number,
    lastGoodBuffer: Buffer, originalCost: number
  ): Promise<void> {
    // Flash credit: grant temporary credits, process, then settle
    const remainingOps = job.operations.slice(failedIndex);
    const retryCost = this.calculateCost(remainingOps);

    // Grant flash credits (will be settled at finalization)
    this.ledger.refundCredits(job.id, retryCost);

    // Charge for retry
    this.ledger.chargeCredits(job.id, retryCost);

    // The settlement happens in finalizeJob - but the refund was already
    // applied to balance, creating a net credit inflation
  }

  private rollbackIntermediates(jobId: string): void {
    const state = this.processingState.get(jobId);
    if (state) {
      state.intermediates = [];
      state.stage = 0;
    }
  }

  private calculateCost(operations: string[]): number {
    const costs: Record<string, number> = {
      'resize': 2, 'rotate': 1, 'blur': 3,
      'sharpen': 3, 'grayscale': 1, 'flip': 1
    };
    return operations.reduce((sum, op) => sum + (costs[op] || 2), 0);
  }

  private async executeOperation(buffer: Buffer, operation: string): Promise<Buffer> {
    const img = sharp(buffer);
    switch (operation) {
      case 'resize': return img.resize(800, 600).toBuffer();
      case 'rotate': return img.rotate(90).toBuffer();
      case 'blur': return img.blur(2.5).toBuffer();
      case 'sharpen': return img.sharpen().toBuffer();
      case 'grayscale': return img.grayscale().toBuffer();
      case 'flip': return img.flip().toBuffer();
      default: throw new Error(`Unknown operation: ${operation}`);
    }
  }
}

